<?php require __DIR__.'/includes/app.php'; require_login(); $totalTarget=array_sum(array_column($_SESSION['goals'],'target')); $total=saved(); $allProgress=$totalTarget ? min(100,round($total/$totalTarget*100,1)):0; page_start('Dashboard','dashboard','Lihat perkembangan tabungan dan pencapaian tujuanmu.'); ?>
<div class="stats-grid"><section class="stat featured"><span>Total terkumpul</span><strong><?=rp($total)?></strong><small><?=count_status('success')?> deposit berhasil</small></section><section class="stat"><span>Total target</span><strong><?=rp($totalTarget)?></strong><small><?=count($_SESSION['goals'])?> tujuan tabungan</small></section><section class="stat"><span>Menunggu pembayaran</span><strong><?=count_status('pending')?> <small>deposit</small></strong><a href="riwayat.php?status=pending">Periksa transaksi</a></section></div>
<div class="two-col dashboard-grid"><section class="panel"><div class="section-title"><h2>Progres keseluruhan</h2><span class="pill"><?=$allProgress?>%</span></div><div class="big-number"><?=rp($total)?><span> dari <?=rp($totalTarget)?></span></div><progress value="<?=$allProgress?>" max="100" aria-label="Progres keseluruhan"><?=$allProgress?>%</progress><div class="progress-caption"><span><?=$allProgress?>% terkumpul</span><span>Sisa <?=rp(max(0,$totalTarget-$total))?></span></div><hr><div class="section-title"><h2>Progres per tujuan</h2><a href="jadwal.php">Atur jadwal</a></div><?php if(!$_SESSION['goals']): empty_state('Belum ada tujuan','Mulai dengan membuat satu jadwal tabungan.','jadwal.php','Buat jadwal'); else: foreach($_SESSION['goals'] as $g): ?><div class="goal-mini"><div><strong><?=e($g['name'])?></strong><span><?=progress($g)?>%</span></div><progress value="<?=progress($g)?>" max="100" aria-label="<?=e($g['name'])?>"><?=progress($g)?>%</progress><p><?=rp(saved($g['id']))?> / <?=rp($g['target'])?></p></div><?php endforeach; endif ?></section><section class="panel"><div class="section-title"><h2>Deposit terbaru</h2><a href="riwayat.php">Semua</a></div><?php if(!$_SESSION['transactions']): ?><div class="empty compact"><?=icon('wallet')?><h3>Belum ada deposit</h3><p>Deposit pertama akan muncul di sini.</p><a class="btn secondary" href="deposit.php">Mulai deposit</a></div><?php else: foreach(array_slice(array_reverse($_SESSION['transactions']),0,5) as $t): ?><a class="transaction-mini" href="pembayaran.php?id=<?=e($t['id'])?>"><div><strong><?=e(goal_name($t['goal_id']))?></strong><small><?=date('d/m/Y H:i',$t['created'])?></small></div><div><strong><?=rp($t['total'])?></strong><?=badge($t['status'])?></div></a><?php endforeach; endif ?></section></div><?php page_end(); ?>
